local UIFishPoolRedeemFishingCouponsPopupDialog = Class("UIFishPoolRedeemFishingCouponsPopupDialog")
local ConstantsFishing = import('Game.UI.Fishing.ConstantsFishing')
local FishingUtils = import('Game.UI.Fishing.FishingUtils')

function UIFishPoolRedeemFishingCouponsPopupDialog:__init() 
    self._fishPlaceId = nil                --渔场id
    self._activityId = nil                 --活动id
    self._data = nil
    self._curSelectId = 0                  --当前选择的兑换id
    self._curSelectInd = 1                 --当前选择的下标

    self._curNum = 1
    self._maxNum = 0
end

function UIFishPoolRedeemFishingCouponsPopupDialog:__delete()
    self._fishPlaceId = nil                --渔场id
    self._activityId = nil                 --活动id  
    self._data = nil
    self._curSelectId = 0                  --当前选择的兑换id
    self._curSelectInd = 1                 --当前选择的下标

    self._curNum = 1
    self._maxNum = 0
end

function UIFishPoolRedeemFishingCouponsPopupDialog:Awake()
    local argument = self.controller.Argument.parameters
    if not argument then
        return
    end
    self._fishPlaceId = checkNumber(argument.fishPlaceId)    
    self._activityId = FishingUtils.GetFishPlaceActivityId(self._fishPlaceId, ConstantsFishing.ActivityType.Summer)
    if self._activityId == 0 then
        return
    end

    self:InitData()
    self:FillSelf()

    SetButtonAction(self.BtnAdd, Bind(self, self.OnBtnAdd))
    SetButtonAction(self.BtnMinus, Bind(self, self.OnBtnReduce))
    SetButtonAction(self.BtnAddTen, Bind(self, self.OnBtnTenAdd))
    SetButtonAction(self.BtnMinusTen, Bind(self, self.OnBtnTenReduce))
    SetButtonAction(self.BtnMinusTen, Bind(self, self.OnBtnTenReduce))
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnExchange))
    self.InputFieldNumber.onValueChanged:AddListener(function(num)
        num = checkNumber(num)
        if num <= 0 then
            self._curNum = 0
        elseif num >= checkNumber(self._maxNum) then
            self._curNum = checkNumber(self._maxNum)
        else
            self._curNum = num    
        end
        self:RefreshSelectNum()
    end)
end

function UIFishPoolRedeemFishingCouponsPopupDialog:InitData()
    local t = FishingUtils.GetAllExchange(self._activityId)
    self._data = {}

    for k, v in pairs(t) do
        local vo = FishingUtils.GetFishExchangeVo(k)
        if vo then
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(vo.cost)

            local path = ""
            if k == 1 then
                path = "Arts/Icons/HomeLabel/vit_icon_diamon_fishingcoupon.png"
            else
                path = "Arts/Icons/HomeLabel/vit_icon_diamon_pressed.png"
            end
            table.insert(self._data, {
                selectImgPath = path,
                text = goodsVo.name,
                func = function()
                    self._curSelectInd = k
                    self._curSelectId = checkNumber(v)
                    self:FillChangeInfo()
                end
            })
        end
    end
end

function UIFishPoolRedeemFishingCouponsPopupDialog:FillSelf()
    local scr = CfUtils.GetLuaScr(self.CommonTabToggleUp.gameObject, "Game.Behaviours.CommonTabToggleUp")
    if isNull(scr) then
        return
    end

    scr:FillToggles(self._data)

    if self._data[checkNumber(self._curSelectInd)] then
        self._data[checkNumber(self._curSelectInd)].func()
    end
end

--兑换
function UIFishPoolRedeemFishingCouponsPopupDialog:OnBtnExchange()
    if self._isExchange then
        return
    end

    if self._curNum < 1 then
        GameUtils.Toast(localize("兑换次数不能为0"))
        return
    elseif self._curNum > self._maxNum then
        GameUtils.Toast(localize("兑换次数不足"))
        return
    end

    local vo = FishingUtils.GetFishExchangeVo(self._curSelectId)
    if not vo then
        return
    end

    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(vo.cost)
    local goods2Vo = GoodsConfMgr:GetInstance():GetGoodsVoById(vo.get)

    local targetNum = self._curNum * checkNumber(vo.costNum)
    local haveNum = GoodsUtils.GetThingNo(vo.cost)
    if targetNum > haveNum then
        GameUtils.Toast(localize("_name_不足", {_name_ = goodsVo.name}))
        return
    end

    self._isExchange = true
    if checkNumber(vo.cost) == Constants.Currency.FreeDiamondId then
        GameUtils.SecondConfirm(localize("是否消耗_num__name_兑换_num2__name2_", {_num_ = self._curNum * checkNumber(vo.costNum), _name_ = goodsVo.name, _num2_ = checkNumber(vo.getNum) * self._curNum, _name2_ = goods2Vo.name}), function()
            fishingComponent:FishingExchangeTicketReq(self._fishPlaceId, self._curSelectId, self._curNum, function()
                if self._data[checkNumber(self._curSelectInd)] then
                    self._data[checkNumber(self._curSelectInd)].func()
                end
                self._isExchange = false
            end)
        end, function()
            self._isExchange = false
        end)
    else
        fishingComponent:FishingExchangeTicketReq(self._fishPlaceId, self._curSelectId, self._curNum, function()
            if self._data[checkNumber(self._curSelectInd)] then
                self._data[checkNumber(self._curSelectInd)].func()
            end
            self._isExchange = false
        end)
    end
end

function UIFishPoolRedeemFishingCouponsPopupDialog:FillChangeInfo()
    if checkNumber(self._curSelectId) == 0 then
        return
    end
    self._maxNum = FishingUtils.GetRemainExchangeNum(self._fishPlaceId, self._curSelectId)

    self:FillItemsInfo()
    CfUtils.FillText(self.TxtLeftNumber, self._maxNum)

    self._curNum = 1
    self:RefreshSelectNum()
end

--道具
function UIFishPoolRedeemFishingCouponsPopupDialog:FillItemsInfo()
    local vo = FishingUtils.GetFishExchangeVo(self._curSelectId)

    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(vo.cost)
    CfUtils.FillImage(self.GroupL.transform:Find("ImgIcon"), GoodsConfMgr:GetInstance():GetPhotoPathById(vo.cost))
    CfUtils.FillText(self.GroupL.transform:Find("NameGroup/TxtName"), goodsVo.name)
    CfUtils.FillText(self.GroupL.transform:Find("NameGroup/TxtNumber"), "x"..vo.costNum)
    CfUtils.FillText(self.GroupL.transform:Find("NumberGroup/TxtGetNumber"), GoodsUtils.GetThingNo(vo.cost))

    goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(vo.get)
    CfUtils.FillImage(self.GroupR.transform:Find("ImgIcon"), GoodsConfMgr:GetInstance():GetPhotoPathById(vo.get))
    CfUtils.FillText(self.GroupR.transform:Find("NameGroup/TxtName"), goodsVo.name)
    CfUtils.FillText(self.GroupR.transform:Find("NameGroup/TxtNumber"), "x"..vo.getNum)
    CfUtils.FillText(self.GroupR.transform:Find("NumberGroup/TxtGetNumber"), GoodsUtils.GetThingNo(vo.get))
end

function UIFishPoolRedeemFishingCouponsPopupDialog:RefreshSelectNum()
    self.InputFieldNumber.text = self._curNum
end

--增加
function UIFishPoolRedeemFishingCouponsPopupDialog:OnBtnAdd()
    if self._curNum >= self._maxNum then
        GameUtils.Toast(localize("已经最大数量了"))
        return 
    end
    self._curNum = self._curNum + 1
    self:RefreshSelectNum()
end

--减少
function UIFishPoolRedeemFishingCouponsPopupDialog:OnBtnReduce()
    if self._curNum <= 0 then
        GameUtils.Toast(localize("已经最低数量了"))
        return 
    end
    self._curNum = self._curNum - 1
    self:RefreshSelectNum()
end

--+10
function UIFishPoolRedeemFishingCouponsPopupDialog:OnBtnTenAdd()
    if self._curNum >= self._maxNum then
        GameUtils.Toast(localize("已经最大数量了"))
        return 
    end

    local num = self._curNum + 10
    self._curNum = (num >= self._maxNum) and self._maxNum or num 
    self:RefreshSelectNum()
end

---10
function UIFishPoolRedeemFishingCouponsPopupDialog:OnBtnTenReduce()
    if self._curNum <= 0 then
        GameUtils.Toast(localize("已经最低数量了"))
        return 
    end

    local num = self._curNum - 10
    self._curNum = (self._curNum <= 0) and 0 or num 
    self:RefreshSelectNum()
end

